// secretsAt returns the secrets that sign a delivery sent at now: the endpoint's secret, then its previous secret while it is
// within SecretOverlap of the last rotation.
func secretsAt(ep store.WebhookEndpoint, now time.Time) []string {
	secrets := []string{ep.Secret}
	if ep.PreviousSecret != "" && ep.RotatedAt != nil && now.Before(ep.RotatedAt.Add(SecretOverlap)) {
		secrets = append(secrets, ep.PreviousSecret)
	}
	return secrets
}

// rotateSecret gives an endpoint a new signing secret. The previous one keeps signing its deliveries for webhooks.SecretOverlap.
func (s *Server) rotateSecret(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	ep, err := s.store.UpdateWebhookEndpoint(p.OrgID, r.PathValue("id"), func(ep *store.WebhookEndpoint) error {
		now := s.clock.Now()
		ep.PreviousSecret, ep.Secret = ep.Secret, webhooks.NewSecret()
		ep.RotatedAt = &now
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, ep)
}

