func TestVerify(t *testing.T) {
	now := time.Unix(1700000000, 0)
	ts := now.Unix()
	body := []byte(`{"id":"evt_1"}`)
	sig := func(secret string) string { return webhooks.Sign(secret, []byte(fmt.Sprintf("%d.%s", ts, body))) }
	valid := fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a"))
	one := []string{"whsec_a"}
	cases := []struct {
		name    string
		header  string
		payload []byte
		secrets []string
		tol     time.Duration
		now     time.Time
		want    error
	}{
		{"valid", valid, body, one, 0, now, nil},
		{"spaces, unknown keys and order", fmt.Sprintf(" v0=zz , v1=%s , t=%d ", sig("whsec_a"), ts), body, one, 0, now, nil},
		{"any of the secrets", valid, body, []string{"whsec_b", "whsec_a"}, 0, now, nil},
		{"any v1 entry", fmt.Sprintf("t=%d,v1=bad,v1=%s", ts, sig("whsec_a")), body, one, 0, now, nil},
		{"wrong secret", valid, body, []string{"whsec_b"}, 0, now, webhooks.ErrSignatureMismatch},
		{"no secrets", valid, body, nil, 0, now, webhooks.ErrSignatureMismatch},
		{"changed payload", valid, []byte(`{"id":"evt_2"}`), one, 0, now, webhooks.ErrSignatureMismatch},
		{"signature of another timestamp", fmt.Sprintf("t=%d,v1=%s", ts+1, sig("whsec_a")), body, one, 0, now, webhooks.ErrSignatureMismatch},
		{"default tolerance, 5 minutes old", valid, body, one, 0, now.Add(5 * time.Minute), nil},
		{"default tolerance, older", valid, body, one, 0, now.Add(5*time.Minute + time.Second), webhooks.ErrTimestampTolerance},
		{"default tolerance, 5 minutes ahead", valid, body, one, 0, now.Add(-5 * time.Minute), nil},
		{"default tolerance, further ahead", valid, body, one, 0, now.Add(-5*time.Minute - time.Second), webhooks.ErrTimestampTolerance},
		{"explicit tolerance", valid, body, one, 10 * time.Second, now.Add(-10 * time.Second), nil},
		{"explicit tolerance exceeded", valid, body, one, 10 * time.Second, now.Add(11 * time.Second), webhooks.ErrTimestampTolerance},
		{"empty header", "", body, one, 0, now, webhooks.ErrMalformedHeader},
		{"pair without =", "t=1,v1", body, one, 0, now, webhooks.ErrMalformedHeader},
		{"empty pair", valid + ",", body, one, 0, now, webhooks.ErrMalformedHeader},
		{"timestamp not an integer", "t=soon,v1=x", body, one, 0, now, webhooks.ErrMalformedHeader},
		{"timestamp with a fraction", "t=1.5,v1=x", body, one, 0, now, webhooks.ErrMalformedHeader},
		{"no timestamp", fmt.Sprintf("v1=%s", sig("whsec_a")), body, one, 0, now, webhooks.ErrNoTimestamp},
		{"no v1 entry", fmt.Sprintf("t=%d,v0=%s", ts, sig("whsec_a")), body, one, 0, now, webhooks.ErrNoSignature},
		{"malformed before no timestamp", "v1=x,oops", body, one, 0, now, webhooks.ErrMalformedHeader},
		{"tolerance before no v1 entry", fmt.Sprintf("t=%d", ts), body, one, 0, now.Add(time.Hour), webhooks.ErrTimestampTolerance},
		{"no v1 entry before mismatch", fmt.Sprintf("t=%d", ts), body, one, 0, now, webhooks.ErrNoSignature},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if err := webhooks.Verify(c.payload, c.header, c.secrets, c.tol, c.now); !errors.Is(err, c.want) {
				t.Fatalf("Verify = %v, want %v", err, c.want)
			}
		})
	}
}

func TestRotatedSecretSignsDeliveries(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	secret := regexp.MustCompile(`^whsec_[0-9a-f]{32}$`)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	original := ep.Secret

	// deliver publishes an event, delivers it and returns what the receiver got.
	deliver := func() apitest.Request {
		t.Helper()
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
			t.Fatal(err)
		}
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("RunDue = %d, %v", n, err)
		}
		reqs := e.HTTP.Requests()
		return reqs[len(reqs)-1]
	}
	header := func(r apitest.Request, secrets ...string) string {
		return webhooks.SignatureHeader(secrets, e.Clock.Now(), r.Body)
	}
	rotate := func() string {
		var rotated store.WebhookEndpoint
		e.MustDo(http.StatusOK, "POST", "/v1/webhook-endpoints/"+ep.ID+"/rotate-secret", e.Acme.Key, nil, &rotated)
		if !secret.MatchString(rotated.Secret) || rotated.Secret == original && rotated.PreviousSecret != original {
			t.Fatalf("rotated endpoint = %+v", rotated)
		}
		return rotated.Secret
	}

	if r := e.Do("POST", "/v1/webhook-endpoints/we_missing/rotate-secret", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("rotating a missing endpoint: %s", r)
	}
	r := deliver()
	if got := r.Header.Get("Tally-Signature"); got != header(r, original) {
		t.Fatalf("before rotation: signature %q", got)
	}

	first := rotate()
	if first == original {
		t.Fatal("rotation kept the secret")
	}
	e.Clock.Advance(time.Hour)
	second := rotate()
	r = deliver()
	got := r.Header.Get("Tally-Signature")
	if want := header(r, second, first); got != want {
		t.Fatalf("after two rotations: signature %q, want %q", got, want)
	}
	if err := webhooks.Verify(r.Body, got, []string{second}, 0, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	if err := webhooks.Verify(r.Body, got, []string{original}, 0, e.Clock.Now()); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("the secret before the previous one still verifies: %v", err)
	}

	e.Clock.Advance(webhooks.SecretOverlap - time.Minute)
	if r = deliver(); r.Header.Get("Tally-Signature") != header(r, second, first) {
		t.Fatalf("23h59m after the last rotation: signature %q", r.Header.Get("Tally-Signature"))
	}
	e.Clock.Advance(time.Minute)
	if r = deliver(); r.Header.Get("Tally-Signature") != header(r, second) {
		t.Fatalf("a day after the last rotation: signature %q", r.Header.Get("Tally-Signature"))
	}
}

